import { MeshBasicNodeMaterial, Group, Mesh, PlaneGeometry, CircleGeometry } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { ink, paper, accent, surface } = config.colors || {};

  const group = new Group();
  group.userData.interactive = true;

  // --- Card plane ----------------------------------------------------------
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: surface,
    side: ctx.THREE.DoubleSide,
  });
  const card = new Mesh(geometry, material);
  card.userData.interactive = true;
  group.add(card);

  // Load texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Stock badge ---------------------------------------------------------
  const badgeGeom = new CircleGeometry(0.08, 16);
  const badgeMat = new MeshBasicNodeMaterial({ color: '#888888', side: ctx.THREE.DoubleSide });
  const badge = new Mesh(badgeGeom, badgeMat);
  badge.position.set(planeWidth / 2 - 0.15, planeHeight / 2 - 0.15, 0.01);
  group.add(badge);
  group.userData.stockBadge = badge; // exposed for external updates

  // --- Focus ring ----------------------------------------------------------
  const ringWidth = planeWidth + 0.08;
  const ringHeight = planeHeight + 0.08;
  const ringGeom = new PlaneGeometry(ringWidth, ringHeight);
  const ringMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0,
    side: ctx.THREE.DoubleSide,
    depthTest: false,
  });
  const ring = new Mesh(ringGeom, ringMat);
  ring.position.z = -0.01;
  group.add(ring);

  // --- Handlers ------------------------------------------------------------
  const timelines = [];

  group.userData.handlers = {
    pointerenter: () => {
      const tl = gsap.to(card.position, {
        y: 0.15,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: 'auto',
      });
      timelines.push(tl);
    },
    pointerleave: () => {
      const tl = gsap.to(card.position, {
        y: 0,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: 'auto',
      });
      timelines.push(tl);
    },
    pointerdown: () => {
      const tl = gsap.to(card.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto',
      });
      timelines.push(tl);
    },
    pointerup: () => {
      const tl = gsap.to(card.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto',
      });
      timelines.push(tl);
    },
    click: () => {
      ctx.emit('hub-journal.select', {});
    },
    focusin: () => {
      ringMat.opacity = 1;
      ringMat.needsUpdate = true;
    },
    focusout: () => {
      ringMat.opacity = 0;
      ringMat.needsUpdate = true;
    },
  };

  // --- Cleanup -------------------------------------------------------------
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    geometry.dispose();
    material.dispose();
    badgeGeom.dispose();
    badgeMat.dispose();
    ringGeom.dispose();
    ringMat.dispose();
  };

  return group;
}
